import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { motion, useScroll, useTransform, useMotionValueEvent } from "framer-motion";
import { cn } from "@/lib/utils";

export interface ScrubbableVideoRevealProps {
  /** Image sequence URLs in order. Use 100–200 highly-compressed WebP / JPEG. */
  frames: string[];
  /** Aspect ratio for the canvas wrapper (e.g. "16 / 10"). */
  aspect?: string;
  /** Multiplier on the scroll travel — total inner = `travel × 100vh`. */
  travel?: number;
  /** Render the surrounding device frame. */
  framed?: boolean;
  /** Pin the canvas via `position: sticky` while user scrolls. */
  sticky?: boolean;
  /** Optional content rendered above the canvas (overlays). */
  children?: React.ReactNode;
  /** Use the window scroll instead of an inner scrollable container. */
  useWindow?: boolean;
  /** Loading strategy for the image preload. */
  preload?: "eager" | "lazy";
  /** Scroll container height (when `useWindow` is false). */
  height?: string;
  className?: string;
}

/**
 * ScrubbableVideoReveal
 *
 * Apple-grade scroll-scrubbed sequence. We never use a `<video>` tag —
 * temporal compression murders reverse-scrubbing. Instead we preload
 * every frame as an `Image`, map `scrollYProgress → frameIndex`, and call
 * `ctx.drawImage()` on every change. The canvas paints on the GPU.
 *
 * Notes:
 *  - Provide 100–200 frames. WebP keeps size sane.
 *  - We resize the canvas with `devicePixelRatio` so it stays sharp on retina.
 *  - We round to the nearest integer index so we don't redraw the same frame.
 */
export function ScrubbableVideoReveal({
  frames,
  aspect = "16 / 10",
  travel = 3,
  framed = true,
  sticky = true,
  useWindow = false,
  children,
  preload = "eager",
  height = "640px",
  className,
}: ScrubbableVideoRevealProps) {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const targetRef = React.useRef<HTMLDivElement>(null);
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const imagesRef = React.useRef<HTMLImageElement[]>([]);
  const lastIndexRef = React.useRef<number>(-1);
  const [loaded, setLoaded] = React.useState(0);

  /* ─── Preload frames ─── */
  React.useEffect(() => {
    let cancelled = false;
    const arr: HTMLImageElement[] = [];
    let count = 0;
    frames.forEach((src, i) => {
      const img = new Image();
      img.decoding = "async";
      img.loading = preload === "lazy" ? "lazy" : "eager";
      img.src = src;
      img.onload = () => {
        if (cancelled) return;
        count++;
        setLoaded(count);
        if (i === 0) drawFrame(0);
      };
      arr[i] = img;
    });
    imagesRef.current = arr;
    return () => {
      cancelled = true;
      imagesRef.current = [];
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [frames.join("|")]);

  /* ─── Resize canvas to its CSS box (DPR-aware) ─── */
  const sizeCanvas = React.useCallback(() => {
    const c = canvasRef.current;
    if (!c) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const rect = c.getBoundingClientRect();
    const w = Math.floor(rect.width * dpr);
    const h = Math.floor(rect.height * dpr);
    if (c.width !== w || c.height !== h) {
      c.width = w;
      c.height = h;
      drawFrame(lastIndexRef.current >= 0 ? lastIndexRef.current : 0);
    }
  }, []);

  React.useEffect(() => {
    sizeCanvas();
    const onResize = () => sizeCanvas();
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, [sizeCanvas]);

  /* ─── Frame painter ─── */
  function drawFrame(index: number) {
    const c = canvasRef.current;
    const img = imagesRef.current[index];
    if (!c || !img || !img.complete || img.naturalWidth === 0) return;
    const ctx = c.getContext("2d");
    if (!ctx) return;
    // Object-fit: cover behaviour.
    const cw = c.width;
    const ch = c.height;
    const iw = img.naturalWidth;
    const ih = img.naturalHeight;
    const cr = cw / ch;
    const ir = iw / ih;
    let dw = cw;
    let dh = ch;
    let dx = 0;
    let dy = 0;
    if (ir > cr) {
      // image wider than canvas → scale to height, crop width
      dh = ch;
      dw = ch * ir;
      dx = (cw - dw) / 2;
    } else {
      dw = cw;
      dh = cw / ir;
      dy = (ch - dh) / 2;
    }
    ctx.clearRect(0, 0, cw, ch);
    ctx.drawImage(img, dx, dy, dw, dh);
    lastIndexRef.current = index;
  }

  /* ─── Scroll → frame index ─── */
  const { scrollYProgress } = useScroll(
    useWindow
      ? { target: targetRef, offset: ["start end", "end start"] }
      : {
          container: containerRef,
          target: targetRef,
          offset: ["start start", "end end"],
        }
  );

  const frameIndex = useTransform(scrollYProgress, (p) => {
    const total = frames.length - 1;
    return Math.round(Math.max(0, Math.min(1, p)) * total);
  });

  useMotionValueEvent(frameIndex, "change", (v) => {
    if (v !== lastIndexRef.current) drawFrame(v);
  });

  /* ─── Markup ─── */
  const innerHeight = `calc(${travel} * 100vh)`;

  return (
    <div
      ref={containerRef}
      className={cn(
        "relative w-full",
        useWindow
          ? ""
          : "scrollbar-hidden overflow-y-auto rounded-3xl border border-[var(--border)] bg-[var(--surface)]",
        className
      )}
      style={useWindow ? undefined : { height }}
    >
      <div ref={targetRef} className="relative w-full" style={{ height: innerHeight }}>
        <div
          className={cn(
            "flex w-full items-center justify-center px-4 py-6 sm:px-8",
            sticky ? "sticky top-0" : "relative"
          )}
          style={!useWindow ? { height } : { height: "100vh" }}
        >
          <div
            className={cn(
              "relative w-full max-w-4xl overflow-hidden rounded-2xl",
              framed
                ? "border border-[var(--border-strong)] bg-[#0a0a0b] p-2 shadow-[0_30px_80px_-30px_rgba(0,0,0,0.6)]"
                : ""
            )}
            style={{ aspectRatio: aspect }}
          >
            <div className="relative h-full w-full overflow-hidden rounded-[14px] bg-black">
              <canvas
                ref={canvasRef}
                className="block h-full w-full"
                aria-label="Scrubbable video sequence"
              />
              {/* Scanline shimmer while frames preload */}
              {loaded < frames.length && (
                <div className="pointer-events-none absolute inset-x-0 bottom-0 flex items-center gap-2 bg-gradient-to-t from-black/60 to-transparent px-3 py-2">
                  <div className="relative h-[3px] flex-1 overflow-hidden rounded-full bg-white/10">
                    <motion.div
                      className="absolute left-0 top-0 h-full w-full origin-left bg-chili-500"
                      initial={{ scaleX: 0 }}
                      animate={{ scaleX: loaded / Math.max(1, frames.length) }}
                      transition={{ type: "spring", stiffness: 220, damping: 28 }}
                      style={{ willChange: "transform" }}
                    />
                  </div>
                  <span className="font-display text-[10px] tabular-nums text-white/72">
                    {loaded}/{frames.length}
                  </span>
                </div>
              )}
              {children && <div className="absolute inset-0">{children}</div>}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
